/****************************************************************************
 * contest2026_113_veladuxingke/app/routine_manager/mimo_integration.h
 *
 * MiMo 在线语音助手集成
 ****************************************************************************/

#ifndef __MIMO_INTEGRATION_H
#define __MIMO_INTEGRATION_H

#include <nuttx/config.h>

#include <stdbool.h>
#include <stdint.h>

#ifdef __cplusplus
extern "C"
{
#endif

#define MIMO_API_KEY_MAX 128
#define MIMO_MODEL_NAME_MAX 64
#define MIMO_TTS_VOICE_MAX 32
#define MIMO_RESPONSE_MAX 2048

/* MiMo 配置 */
struct mimo_config_s
{
  char api_key[MIMO_API_KEY_MAX];
  char model[MIMO_MODEL_NAME_MAX];
  char tts_voice[MIMO_TTS_VOICE_MAX];
  bool enabled;
};

/* MiMo ASR 结果 */
struct mimo_asr_result_s
{
  char text[512];
  int confidence;
  bool success;
};

/* MiMo LLM 响应 */
struct mimo_llm_response_s
{
  char text[MIMO_RESPONSE_MAX];
  bool success;
  int error_code;
};

/* MiMo TTS 结果 */
struct mimo_tts_result_s
{
  char audio_path[128];
  uint32_t duration_ms;
  bool success;
};

/* MiMo 服务状态 */
enum mimo_service_state_e
{
  MIMO_STATE_IDLE = 0,
  MIMO_STATE_ASR_PROCESSING,
  MIMO_STATE_LLM_PROCESSING,
  MIMO_STATE_TTS_PROCESSING,
  MIMO_STATE_ERROR
};

/* MiMo 服务实例 */
struct mimo_service_s
{
  struct mimo_config_s config;
  enum mimo_service_state_e state;
  bool initialized;
};

/**
 * 初始化 MiMo 服务
 */
int mimo_service_init(FAR struct mimo_service_s *service,
                      FAR const struct mimo_config_s *config);

/**
 * ASR: 语音转文字
 * @param service MiMo 服务实例
 * @param pcm_path 输入 PCM 文件路径 (16kHz, 16-bit, mono)
 * @param result 输出 ASR 结果
 */
int mimo_asr(FAR struct mimo_service_s *service,
             FAR const char *pcm_path,
             FAR struct mimo_asr_result_s *result);

/**
 * LLM: 对话理解与生成
 * @param service MiMo 服务实例
 * @param user_text 用户输入文本
 * @param response 输出 LLM 响应
 */
int mimo_llm_chat(FAR struct mimo_service_s *service,
                  FAR const char *user_text,
                  FAR struct mimo_llm_response_s *response);

/**
 * TTS: 文字转语音
 * @param service MiMo 服务实例
 * @param text 输入文本
 * @param result 输出 TTS 结果（包含音频文件路径）
 */
int mimo_tts(FAR struct mimo_service_s *service,
             FAR const char *text,
             FAR struct mimo_tts_result_s *result);

/**
 * 更新配置
 */
int mimo_service_update_config(FAR struct mimo_service_s *service,
                               FAR const struct mimo_config_s *config);

/**
 * 关闭服务
 */
void mimo_service_shutdown(FAR struct mimo_service_s *service);

#ifdef __cplusplus
}
#endif

#endif /* __MIMO_INTEGRATION_H */

/****************************************************************************
 * contest2026_113_veladuxingke/app/routine_manager/mimo_integration.c
 *
 * MiMo 在线语音助手集成实现
 ****************************************************************************/

#include <nuttx/config.h>

#include <errno.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <syslog.h>
#include <unistd.h>
#include <sys/stat.h>

#include "mimo_integration.h"

#define MIMO_API_BASE_URL "https://api.xiaomimimo.com/v1"
#define MIMO_API_BASE_URL_TP "https://token-plan-cn.xiaomimimo.com/v1"
#define MIMO_TMP_DIR "/data/mimo_tmp"
#define MIMO_ASR_OUTPUT "/data/mimo_tmp/asr_result.txt"
#define MIMO_TTS_OUTPUT "/data/mimo_tmp/tts_output.pcm"

/****************************************************************************
 * Private Functions
 ****************************************************************************/

static const char *mimo_get_base_url(const char *api_key)
{
  if (strncmp(api_key, "tp-", 3) == 0)
    {
      return MIMO_API_BASE_URL_TP;
    }
  return MIMO_API_BASE_URL;
}

static int mimo_ensure_tmp_dir(void)
{
  struct stat st;

  if (stat(MIMO_TMP_DIR, &st) != 0)
    {
      if (mkdir(MIMO_TMP_DIR, 0755) != 0)
        {
          syslog(LOG_ERR, "Failed to create %s: %d\n", MIMO_TMP_DIR, errno);
          return -errno;
        }
    }

  return OK;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int mimo_service_init(FAR struct mimo_service_s *service,
                      FAR const struct mimo_config_s *config)
{
  if (service == NULL || config == NULL)
    {
      return -EINVAL;
    }

  memset(service, 0, sizeof(struct mimo_service_s));
  memcpy(&service->config, config, sizeof(struct mimo_config_s));

  /* 设置默认模型和音色 */
  if (strlen(service->config.model) == 0)
    {
      strncpy(service->config.model, "mimo-v2.5", MIMO_MODEL_NAME_MAX - 1);
    }

  if (strlen(service->config.tts_voice) == 0)
    {
      strncpy(service->config.tts_voice, "冰糖", MIMO_TTS_VOICE_MAX - 1);
    }

  service->state = MIMO_STATE_IDLE;
  service->initialized = true;

  syslog(LOG_INFO, "MiMo service initialized with model: %s, voice: %s\n",
         service->config.model, service->config.tts_voice);

  return OK;
}

int mimo_asr(FAR struct mimo_service_s *service,
             FAR const char *pcm_path,
             FAR struct mimo_asr_result_s *result)
{
  char cmd[512];
  FILE *fp;
  int ret;

  if (service == NULL || pcm_path == NULL || result == NULL)
    {
      return -EINVAL;
    }

  if (!service->config.enabled || strlen(service->config.api_key) == 0)
    {
      syslog(LOG_WARNING, "MiMo service not enabled or API key not set\n");
      return -ENOTSUP;
    }

  ret = mimo_ensure_tmp_dir();
  if (ret < 0)
    {
      return ret;
    }

  memset(result, 0, sizeof(struct mimo_asr_result_s));
  service->state = MIMO_STATE_ASR_PROCESSING;

  /* 使用 curl 调用 MiMo ASR API
   * 注意：这是简化实现，实际应该使用 ai_agent 的 MiMo 集成
   */
  const char *base_url = mimo_get_base_url(service->config.api_key);

  snprintf(cmd, sizeof(cmd),
           "curl -s -X POST '%s/audio/transcriptions' "
           "-H 'api-key: %s' "
           "-H 'Content-Type: multipart/form-data' "
           "-F 'file=@%s' "
           "-F 'model=%s' "
           "> %s",
           base_url,
           service->config.api_key,
           pcm_path,
           service->config.model,
           MIMO_ASR_OUTPUT);

  syslog(LOG_INFO, "Calling MiMo ASR...\n");
  ret = system(cmd);

  if (ret != 0)
    {
      syslog(LOG_ERR, "MiMo ASR failed: %d\n", ret);
      service->state = MIMO_STATE_ERROR;
      return -EIO;
    }

  /* 读取结果 */
  fp = fopen(MIMO_ASR_OUTPUT, "r");
  if (fp == NULL)
    {
      syslog(LOG_ERR, "Failed to open ASR result file\n");
      service->state = MIMO_STATE_ERROR;
      return -EIO;
    }

  /* 简化的 JSON 解析 - 实际应该使用 cJSON */
  char line[512];
  if (fgets(line, sizeof(line), fp) != NULL)
    {
      /* 假设返回格式: {"text": "识别结果"} */
      char *text_start = strstr(line, "\"text\":");
      if (text_start != NULL)
        {
          text_start = strchr(text_start, '"');
          if (text_start != NULL)
            {
              text_start = strchr(text_start + 1, '"');
              if (text_start != NULL)
                {
                  text_start++;
                  char *text_end = strchr(text_start, '"');
                  if (text_end != NULL)
                    {
                      size_t len = text_end - text_start;
                      if (len < sizeof(result->text))
                        {
                          strncpy(result->text, text_start, len);
                          result->text[len] = '\0';
                          result->success = true;
                          result->confidence = 95; /* 默认置信度 */
                        }
                    }
                }
            }
        }
    }

  fclose(fp);
  service->state = MIMO_STATE_IDLE;

  if (result->success)
    {
      syslog(LOG_INFO, "MiMo ASR result: %s\n", result->text);
    }
  else
    {
      syslog(LOG_WARNING, "MiMo ASR parsing failed\n");
    }

  return result->success ? OK : -ENODATA;
}

int mimo_llm_chat(FAR struct mimo_service_s *service,
                  FAR const char *user_text,
                  FAR struct mimo_llm_response_s *response)
{
  char cmd[1024];
  char escaped_text[512];
  FILE *fp;
  int ret;

  if (service == NULL || user_text == NULL || response == NULL)
    {
      return -EINVAL;
    }

  if (!service->config.enabled || strlen(service->config.api_key) == 0)
    {
      return -ENOTSUP;
    }

  ret = mimo_ensure_tmp_dir();
  if (ret < 0)
    {
      return ret;
    }

  memset(response, 0, sizeof(struct mimo_llm_response_s));
  service->state = MIMO_STATE_LLM_PROCESSING;

  /* 转义特殊字符 */
  size_t i, j = 0;
  for (i = 0; i < strlen(user_text) && j < sizeof(escaped_text) - 2; i++)
    {
      if (user_text[i] == '"' || user_text[i] == '\\')
        {
          escaped_text[j++] = '\\';
        }
      escaped_text[j++] = user_text[i];
    }
  escaped_text[j] = '\0';

  const char *base_url = mimo_get_base_url(service->config.api_key);
  const char *llm_result = "/data/mimo_tmp/llm_result.txt";

  /* 构建请求 */
  snprintf(cmd, sizeof(cmd),
           "curl -s -X POST '%s/chat/completions' "
           "-H 'api-key: %s' "
           "-H 'Content-Type: application/json' "
           "-d '{\"model\":\"%s\",\"messages\":[{\"role\":\"system\",\"content\":\"你是 OpenVela 智能桌面助手，回答要简洁友好。\"},{\"role\":\"user\",\"content\":\"%s\"}],\"thinking\":\"disabled\",\"temperature\":1.0}' "
           "> %s",
           base_url,
           service->config.api_key,
           service->config.model,
           escaped_text,
           llm_result);

  syslog(LOG_INFO, "Calling MiMo LLM for: %s\n", user_text);
  ret = system(cmd);

  if (ret != 0)
    {
      syslog(LOG_ERR, "MiMo LLM failed: %d\n", ret);
      service->state = MIMO_STATE_ERROR;
      response->error_code = ret;
      return -EIO;
    }

  /* 读取响应 */
  fp = fopen(llm_result, "r");
  if (fp == NULL)
    {
      service->state = MIMO_STATE_ERROR;
      return -EIO;
    }

  /* 简化的响应解析 */
  char buffer[MIMO_RESPONSE_MAX];
  size_t read_len = fread(buffer, 1, sizeof(buffer) - 1, fp);
  buffer[read_len] = '\0';
  fclose(fp);

  /* 查找 "content": "..." */
  char *content_start = strstr(buffer, "\"content\":");
  if (content_start != NULL)
    {
      content_start = strchr(content_start, '"');
      if (content_start != NULL)
        {
          content_start = strchr(content_start + 1, '"');
          if (content_start != NULL)
            {
              content_start++;
              char *content_end = content_start;
              int quote_count = 0;

              /* 查找匹配的结束引号 */
              while (*content_end != '\0')
                {
                  if (*content_end == '"' && *(content_end - 1) != '\\')
                    {
                      break;
                    }
                  content_end++;
                }

              if (*content_end == '"')
                {
                  size_t len = content_end - content_start;
                  if (len < sizeof(response->text))
                    {
                      strncpy(response->text, content_start, len);
                      response->text[len] = '\0';
                      response->success = true;
                    }
                }
            }
        }
    }

  service->state = MIMO_STATE_IDLE;

  if (response->success)
    {
      syslog(LOG_INFO, "MiMo LLM response: %s\n", response->text);
    }

  return response->success ? OK : -ENODATA;
}

int mimo_tts(FAR struct mimo_service_s *service,
             FAR const char *text,
             FAR struct mimo_tts_result_s *result)
{
  char cmd[1024];
  char escaped_text[512];
  int ret;
  struct stat st;

  if (service == NULL || text == NULL || result == NULL)
    {
      return -EINVAL;
    }

  if (!service->config.enabled || strlen(service->config.api_key) == 0)
    {
      return -ENOTSUP;
    }

  ret = mimo_ensure_tmp_dir();
  if (ret < 0)
    {
      return ret;
    }

  memset(result, 0, sizeof(struct mimo_tts_result_s));
  service->state = MIMO_STATE_TTS_PROCESSING;

  /* 转义文本 */
  size_t i, j = 0;
  for (i = 0; i < strlen(text) && j < sizeof(escaped_text) - 2; i++)
    {
      if (text[i] == '"' || text[i] == '\\')
        {
          escaped_text[j++] = '\\';
        }
      escaped_text[j++] = text[i];
    }
  escaped_text[j] = '\0';

  const char *base_url = mimo_get_base_url(service->config.api_key);

  /* 调用 MiMo TTS */
  snprintf(cmd, sizeof(cmd),
           "curl -s -X POST '%s/audio/speech' "
           "-H 'api-key: %s' "
           "-H 'Content-Type: application/json' "
           "-d '{\"model\":\"mimo-v2.5-tts\",\"input\":\"%s\",\"voice\":\"%s\",\"response_format\":\"pcm\"}' "
           "--output %s",
           base_url,
           service->config.api_key,
           escaped_text,
           service->config.tts_voice,
           MIMO_TTS_OUTPUT);

  syslog(LOG_INFO, "Calling MiMo TTS for: %s\n", text);
  ret = system(cmd);

  if (ret != 0)
    {
      syslog(LOG_ERR, "MiMo TTS failed: %d\n", ret);
      service->state = MIMO_STATE_ERROR;
      return -EIO;
    }

  /* 检查输出文件 */
  if (stat(MIMO_TTS_OUTPUT, &st) == 0 && st.st_size > 0)
    {
      strncpy(result->audio_path, MIMO_TTS_OUTPUT, sizeof(result->audio_path) - 1);
      result->duration_ms = (st.st_size * 1000) / (16000 * 2); /* 16kHz, 16-bit */
      result->success = true;
      syslog(LOG_INFO, "MiMo TTS output: %s (%u ms)\n",
             result->audio_path, result->duration_ms);
    }
  else
    {
      syslog(LOG_ERR, "MiMo TTS output file invalid\n");
      service->state = MIMO_STATE_ERROR;
      return -EIO;
    }

  service->state = MIMO_STATE_IDLE;
  return OK;
}

int mimo_service_update_config(FAR struct mimo_service_s *service,
                               FAR const struct mimo_config_s *config)
{
  if (service == NULL || config == NULL)
    {
      return -EINVAL;
    }

  memcpy(&service->config, config, sizeof(struct mimo_config_s));

  syslog(LOG_INFO, "MiMo config updated: enabled=%d, model=%s\n",
         service->config.enabled, service->config.model);

  return OK;
}

void mimo_service_shutdown(FAR struct mimo_service_s *service)
{
  if (service != NULL)
    {
      service->initialized = false;
      service->state = MIMO_STATE_IDLE;
      syslog(LOG_INFO, "MiMo service shutdown\n");
    }
}

