/****************************************************************************
 * contest2026_113_veladuxingke/app/routine_manager/voice_recognizer_online.h
 *
 * 在线语音识别（支持唤醒词 + MiMo）
 ****************************************************************************/

#ifndef __VOICE_RECOGNIZER_ONLINE_H
#define __VOICE_RECOGNIZER_ONLINE_H

#include <nuttx/config.h>

#include <stdbool.h>
#include <stdint.h>

#include "mimo_integration.h"
#include "voice_recognizer.h"

#ifdef __cplusplus
extern "C"
{
#endif

/* 扩展的语音命令，包含唤醒词 */
enum voice_command_online_e
{
  VOICE_COMMAND_ONLINE_NONE = 0,
  VOICE_COMMAND_ONLINE_WAKE_WORD,           /* 你好，openvela */
  VOICE_COMMAND_ONLINE_QUERY_TEMPERATURE,   /* 离线固定指令 */
  VOICE_COMMAND_ONLINE_QUERY_HUMIDITY,
  VOICE_COMMAND_ONLINE_QUERY_LIGHT,
  VOICE_COMMAND_ONLINE_QUERY_AIR_QUALITY,
  VOICE_COMMAND_ONLINE_CHAT,                /* MiMo 智能对话 */
  VOICE_COMMAND_ONLINE_UNKNOWN
};

/* 在线语音识别结果 */
struct voice_recognition_online_result_s
{
  enum voice_command_online_e command;
  char text[512];                /* ASR 文本（在线模式） */
  char response[2048];           /* LLM 响应（在线模式） */
  uint16_t score;
  bool is_wake_word;
  bool is_online_mode;
  bool success;
};

/**
 * 在线语音识别（支持唤醒词检测 + MiMo 对话）
 *
 * @param pcm_path PCM 文件路径
 * @param mimo_service MiMo 服务实例（NULL 表示离线模式）
 * @param online_mode true = 在线模式，false = 离线模式
 * @param result 输出识别结果
 * @return 0 成功，负数为错误码
 */
int voice_recognizer_online_recognize(
  FAR const char *pcm_path,
  FAR struct mimo_service_s *mimo_service,
  bool online_mode,
  FAR struct voice_recognition_online_result_s *result);

/**
 * 检测是否为唤醒词 "你好，openvela"
 *
 * @param pcm_path PCM 文件路径
 * @param score 输出置信度分数
 * @return true = 检测到唤醒词，false = 未检测到
 */
bool voice_recognizer_detect_wake_word(FAR const char *pcm_path,
                                       FAR uint16_t *score);

#ifdef __cplusplus
}
#endif

#endif /* __VOICE_RECOGNIZER_ONLINE_H */

/****************************************************************************
 * contest2026_113_veladuxingke/app/routine_manager/voice_recognizer_online.c
 *
 * 在线语音识别实现
 ****************************************************************************/

#include <nuttx/config.h>

#include <errno.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <syslog.h>

#include "voice_recognizer_online.h"

/****************************************************************************
 * Private Functions
 ****************************************************************************/

/* 简化的唤醒词检测 - 在实际应用中应该扩展 KWS 模型
 * 这里使用离线 KWS 模型的 VOICE_COMMAND_WAKE 类别
 */
bool voice_recognizer_detect_wake_word(FAR const char *pcm_path,
                                       FAR uint16_t *score)
{
  struct voice_recognition_result_s result;
  int ret;

  if (pcm_path == NULL || score == NULL)
    {
      return false;
    }

  /* 调用现有的 KWS 识别器 */
  ret = voice_recognizer_recognize(pcm_path, &result);
  if (ret < 0)
    {
      syslog(LOG_WARNING, "Wake word detection failed: %d\n", ret);
      return false;
    }

  *score = result.score;

  /* 检查是否为唤醒词类别 */
  if (result.command == VOICE_COMMAND_WAKE && result.score > 180)
    {
      syslog(LOG_INFO, "Wake word detected! Score: %u\n", result.score);
      return true;
    }

  return false;
}

/* 判断是否为离线固定指令查询 */
static enum voice_command_online_e
map_offline_command(enum voice_command_e cmd)
{
  switch (cmd)
    {
      case VOICE_COMMAND_QUERY_TEMPERATURE:
        return VOICE_COMMAND_ONLINE_QUERY_TEMPERATURE;
      case VOICE_COMMAND_QUERY_HUMIDITY:
        return VOICE_COMMAND_ONLINE_QUERY_HUMIDITY;
      case VOICE_COMMAND_QUERY_LIGHT:
        return VOICE_COMMAND_ONLINE_QUERY_LIGHT;
      case VOICE_COMMAND_QUERY_AIR_QUALITY:
        return VOICE_COMMAND_ONLINE_QUERY_AIR_QUALITY;
      case VOICE_COMMAND_WAKE:
        return VOICE_COMMAND_ONLINE_WAKE_WORD;
      default:
        return VOICE_COMMAND_ONLINE_UNKNOWN;
    }
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int voice_recognizer_online_recognize(
  FAR const char *pcm_path,
  FAR struct mimo_service_s *mimo_service,
  bool online_mode,
  FAR struct voice_recognition_online_result_s *result)
{
  struct voice_recognition_result_s offline_result;
  int ret;

  if (pcm_path == NULL || result == NULL)
    {
      return -EINVAL;
    }

  memset(result, 0, sizeof(struct voice_recognition_online_result_s));
  result->is_online_mode = online_mode;

  /* 步骤 1: 首先用 KWS 检测唤醒词或固定指令 */
  ret = voice_recognizer_recognize(pcm_path, &offline_result);
  if (ret < 0)
    {
      syslog(LOG_ERR, "Offline recognition failed: %d\n", ret);
      return ret;
    }

  result->score = offline_result.score;
  result->command = map_offline_command(offline_result.command);

  /* 检测到唤醒词 */
  if (offline_result.command == VOICE_COMMAND_WAKE)
    {
      result->is_wake_word = true;
      result->success = true;
      syslog(LOG_INFO, "Wake word detected in online recognizer\n");
      return OK;
    }

  /* 检测到固定指令（温度、湿度、光照、空气质量） */
  if (offline_result.command >= VOICE_COMMAND_QUERY_TEMPERATURE &&
      offline_result.command <= VOICE_COMMAND_QUERY_AIR_QUALITY)
    {
      result->success = true;
      syslog(LOG_INFO, "Fixed command detected: %d\n", result->command);
      return OK;
    }

  /* 步骤 2: 如果是在线模式且没有识别为固定指令，调用 MiMo */
  if (online_mode && mimo_service != NULL &&
      mimo_service->config.enabled &&
      strlen(mimo_service->config.api_key) > 0)
    {
      struct mimo_asr_result_s asr_result;
      struct mimo_llm_response_s llm_response;

      syslog(LOG_INFO, "Using online MiMo for recognition\n");

      /* ASR: 语音转文字 */
      ret = mimo_asr(mimo_service, pcm_path, &asr_result);
      if (ret < 0 || !asr_result.success)
        {
          syslog(LOG_WARNING, "MiMo ASR failed, falling back to offline\n");
          result->command = VOICE_COMMAND_ONLINE_UNKNOWN;
          result->success = false;
          return -ENODATA;
        }

      strncpy(result->text, asr_result.text, sizeof(result->text) - 1);
      syslog(LOG_INFO, "ASR result: %s\n", result->text);

      /* LLM: 对话理解与生成 */
      ret = mimo_llm_chat(mimo_service, asr_result.text, &llm_response);
      if (ret < 0 || !llm_response.success)
        {
          syslog(LOG_WARNING, "MiMo LLM failed\n");
          result->command = VOICE_COMMAND_ONLINE_CHAT;
          result->success = false;
          return -ENODATA;
        }

      strncpy(result->response, llm_response.text, sizeof(result->response) - 1);
      syslog(LOG_INFO, "LLM response: %s\n", result->response);

      result->command = VOICE_COMMAND_ONLINE_CHAT;
      result->success = true;
      return OK;
    }

  /* 离线模式或在线模式失败 */
  result->command = VOICE_COMMAND_ONLINE_UNKNOWN;
  result->success = false;
  syslog(LOG_INFO, "Voice recognition returned unknown\n");

  return OK;
}

